from pathlib import Path
import hashlib,json,subprocess,datetime
E=Path(__file__).resolve().parent;plan=json.loads((E/'assignment-plan.json').read_text());F=Path(plan['owned_root'])/'frozen';m=json.loads((F/'installed-artifact-manifest.json').read_text());v=json.loads(subprocess.check_output(['node',str(F/'freeze-repair.mjs'),'--verify'],text=True));hashfile=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
files=['installed-artifact-manifest.json','installed-dependency-tree.json','installed-artifact.tar.gz','synapsor-runner-1.8.0.tgz','synapsor-spec-1.11.0.tgz'];entries={r['path']:r['sha256'] for r in m['records'] if r.get('kind')=='file' and r['path'] in ['node_modules/@synapsor/runner/dist/'+n for n in ['cli.js','runner.mjs','runtime.mjs','authoring.mjs','shadow.mjs']]};assert len(entries)==5
fragments=['HOST-RESOLVED','A paragraph operator_message_id supports that passage'];present={s:[f for f in entries if s in (F/'installed'/f).read_text()] for s in fragments};assert all(present.values())
r={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_commit':m['source_commit'],'product_commit':m['product_commit'],'test_commit':m['test_commit'],'installed_root':m['installed_root'],'installed_tree_sha256':m['installed_tree_sha256'],'entries':len(m['records']),'runner_version':m['runner_version'],'spec_version':m['spec_version'],'package_lock_sha256':m['package_lock_sha256'],'node':m['node'],'verification':v,'files':{f:hashfile(F/f) for f in files},'entrypoints':entries,'installed_component_and_prompt_code_present':present}
with (E/'installed-artifact-identity.json').open('x') as f:f.write(json.dumps(r,indent=2)+'\n')
print(json.dumps({'tree':r['installed_tree_sha256'],'source':r['source_commit'],'product':r['product_commit'],'entries':r['entries']}))
